#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M, Q;
    cin >> N >> M >> Q;

    vector<int> prop(N + 2, 0);
    for (int i = 0; i < M; i++) {
        int x;
        cin >> x;
        prop[x] = 1;
    }

    // prefix sum of propellers
    vector<int> pref(N + 2, 0);
    for (int i = 1; i <= N; i++) {
        pref[i] = pref[i - 1] + prop[i];
    }

    // For each possible arrow length L, compute minimum losses
    // Losses for length L = N - max number of positions covered by a propeller
    // That is, for each starting point s (0 <= s <= N-L), the arrow covers [s+1, s+L]
    // We want max count of propellers in such interval.
    // Then losses = N - that max count.

    vector<int> minLossForLen(N + 1, N);
    for (int L = 1; L <= N; L++) {
        int maxProp = 0;
        for (int s = 0; s + L <= N; s++) {
            int cnt = pref[s + L] - pref[s];
            maxProp = max(maxProp, cnt);
        }
        minLossForLen[L] = N - maxProp;
    }

    // Precompute answer for each l
    // answer[l] = minimal length with minLossForLen[L] <= l
    vector<int> ans(N + 1, N + 1);
    int bestLen = N;
    for (int l = N; l >= 0; l--) {
        while (bestLen > 0 && minLossForLen[bestLen] > l) {
            bestLen--;
        }
        ans[l] = bestLen;
    }

    while (Q--) {
        int l;
        cin >> l;
        if (l > N) l = N;
        cout << ans[l] << '\n';
    }

    return 0;
}

