#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 N, M, Q;
    cin >> N >> M >> Q;

    vector<int64> a(M);
    for (int i = 0; i < M; ++i) cin >> a[i];
    sort(a.begin(), a.end());

    // Add boundaries 0 and N+1 to handle gaps uniformly.
    vector<int64> p;
    p.reserve(M + 2);
    p.push_back(0);
    for (auto x : a) p.push_back(x);
    p.push_back(N + 1);

    // cnt[g] = how many gaps of length g exist between consecutive propellers/boundaries.
    // A gap length g means there are g positions with no propeller in that interval.
    vector<int64> cnt(N + 1, 0);
    for (int i = 0; i + 1 < (int)p.size(); ++i) {
        int64 g = p[i + 1] - p[i] - 1;
        if (g >= 0) cnt[g]++;
    }

    // For arrow length L:
    // losses(L) = sum over each gap g of cnt[g] * max(0, g - L + 1)
    //
    // We preprocess:
    //   C[t] = number of gaps with length >= t
    // Then:
    //   losses(L+1) = losses(L) - C[L]
    // because increasing L by 1 reduces each gap of length >= L by exactly 1.
    vector<int64> ge(N + 2, 0); // ge[t] for t in [0..N+1]
    for (int64 g = N; g >= 0; --g) ge[g] = ge[g + 1] + cnt[g];

    vector<int64> loss(N + 2, 0); // loss[L], 1 <= L <= N+1
    int64 cur = 0;
    for (int64 g = 0; g <= N; ++g) cur += cnt[g] * g; // loss[1]
    loss[1] = cur;
    for (int64 L = 1; L <= N; ++L) {
        loss[L + 1] = loss[L] - ge[L];
    }

    // loss[L] is non-increasing in L.
    // For each query l, find minimum L such that loss[L] <= l.
    while (Q--) {
        int64 l;
        cin >> l;
        int64 ans = lower_bound(loss.begin() + 1, loss.begin() + N + 2, l,
                                [](int64 x, int64 val) { return x > val; }) - loss.begin();
        // lower_bound with descending condition:
        // first position where !(loss[pos] > l), i.e. loss[pos] <= l.
        cout << ans << '\n';
    }

    return 0;
}

#include <stdio.h>
