#define MAXN 2000005

int has_propeller[MAXN];
int min_len_for_no_loss[MAXN]; // for each position x, smallest arrow length to avoid loss at x
int loss_count_for_len[MAXN];  // total losses for given arrow length

int main() {
    int N, M, Q;
    scanf("%d %d %d", &N, &M, &Q);

    // Read propeller positions
    for (int i = 0; i < M; i++) {
        int p;
        scanf("%d", &p);
        has_propeller[p] = 1;
    }

    // Initialize min_len_for_no_loss to large value
    for (int i = 1; i <= N; i++) {
        min_len_for_no_loss[i] = N + 1;
    }

    // For each propeller position, update min length for positions to its right
    int last_propeller = -1;
    for (int x = 1; x <= N; x++) {
        if (has_propeller[x]) {
            last_propeller = x;
        }
        if (last_propeller != -1) {
            int needed = x - last_propeller + 1;
            if (needed < min_len_for_no_loss[x]) {
                min_len_for_no_loss[x] = needed;
            }
        }
    }

    last_propeller = -1;
    for (int x = N; x >= 1; x--) {
        if (has_propeller[x]) {
            last_propeller = x;
        }
        if (last_propeller != -1) {
            int needed = last_propeller - x + 1;
            if (needed < min_len_for_no_loss[x]) {
                min_len_for_no_loss[x] = needed;
            }
        }
    }

    // Build loss count per length
    for (int x = 1; x <= N; x++) {
        int minL = min_len_for_no_loss[x];
        if (minL > N) minL = N + 1;
        loss_count_for_len[minL]++;
    }

    // Convert to cumulative: loss_count_for_len[L] = total losses for arrow length L
    for (int L = 1; L <= N; L++) {
        loss_count_for_len[L] += loss_count_for_len[L - 1];
    }

    // Answer queries
    while (Q--) {
        int l;
        scanf("%d", &l);
        // binary search smallest L such that losses <= l
        int lo = 1, hi = N, ans = N;
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            if (loss_count_for_len[mid] <= l) {
                ans = mid;
                hi = mid - 1;
            } else {
                lo = mid + 1;
            }
        }
        printf("%d\n", ans);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int cmp_desc(const void *a, const void *b) {
    return (*(int*)b) - (*(int*)a);
}

int main() {
    int N, M, Q;
    scanf("%d %d %d", &N, &M, &Q);

    int *prop = malloc(M * sizeof(int));
    for (int i = 0; i < M; i++) scanf("%d", &prop[i]);

    // Sort propellers
    // Use qsort ascending
    int cmp_asc(const void *a, const void *b) { return (*(int*)a)-(*(int*)b); }
    qsort(prop, M, sizeof(int), cmp_asc);

    // For each x in 1..N, compute d(x) = x - prev(x)
    int *d = malloc(N * sizeof(int));
    int pi = 0;
    int last_prop = -1; // no propeller seen yet, use -infinity -> d = x - (-inf) means loss always
    // Actually if no propeller <= x, prev(x) doesn't exist, d(x) = infinity -> always a loss regardless of L
    // We can set d(x) = N+1 in that case (larger than any possible L)

    pi = 0;
    int cur_prop = -1;
    for (int x = 1; x <= N; x++) {
        while (pi < M && prop[pi] <= x) { cur_prop = prop[pi]; pi++; }
        if (cur_prop < 0) d[x-1] = N+1;
        else d[x-1] = x - cur_prop;
    }

    qsort(d, N, sizeof(int), cmp_desc);

    for (int q = 0; q < Q; q++) {
        int l; scanf("%d", &l);
        int ans;
        if (l >= N) ans = 1;
        else ans = d[l]; // d[l] is the (l+1)-th largest
        if (ans < 1) ans = 1;
        printf("%d\n", ans);
    }
    free(prop); free(d);
    return 0;
}

