typedef long long ll;

static int cmp_ll(const void *a, const void *b) {
    ll x = *(const ll*)a;
    ll y = *(const ll*)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main(void) {
    ll N, M, Q;
    if (scanf("%lld %lld %lld", &N, &M, &Q) != 3) return 0;

    ll *p = NULL;
    if (M > 0) {
        p = (ll*)malloc(sizeof(ll) * M);
        for (ll i = 0; i < M; i++) scanf("%lld", &p[i]);
        qsort(p, M, sizeof(ll), cmp_ll);
    }

    /*
      For a fixed arrow length L, at evaluation position t (1..N),
      it is a loss iff interval [t-L, t] contains no propeller.

      Let d(t) = distance from t to the nearest propeller on its left (including itself).
      Then [t-L, t] contains a propeller iff d(t) <= L.
      So losses for length L are exactly count of t with d(t) > L.

      Over each gap between consecutive propellers (and boundaries), d(t) forms ranges:
      If previous propeller is at a, then for t in [a+1 .. next_propeller-1], d(t)=1,2,3,...
      Also before first propeller at f, for t in [1..f-1], there is no left propeller at all,
      so always loss regardless of L (equivalent to infinite distance).
      After last propeller at last, for t in [last+1..N], d(t)=1,2,...

      Therefore:
      mandatory losses = positions before first propeller, i.e. first_propeller-1
      reducible losses count for threshold L:
         sum over each segment after a propeller of max(segment_len - L, 0)
      where segment_len is:
         gaps between consecutive propellers: p[i+1]-p[i]-1
         tail after last propeller: N-p[last]
      If there is no propeller, all N positions are mandatory losses.

      We need minimum L such that total_losses(L) <= query_l.
    */

    if (M == 0) {
        for (ll qi = 0; qi < Q; qi++) {
            ll lim;
            scanf("%lld", &lim);
            if (lim >= N) printf("1\n");
            else printf("-1\n");
        }
        free(p);
        return 0;
    }

    ll mandatory = p[0] - 1; // unavoidable losses
    ll K = M; // number of reducible segments = (M-1) internal gaps + 1 tail = M
    ll *seg = (ll*)malloc(sizeof(ll) * K);

    for (ll i = 0; i + 1 < M; i++) seg[i] = p[i + 1] - p[i] - 1;
    seg[M - 1] = N - p[M - 1];

    qsort(seg, K, sizeof(ll), cmp_ll);

    ll *pref = (ll*)malloc(sizeof(ll) * (K + 1));
    pref[0] = 0;
    for (ll i = 0; i < K; i++) pref[i + 1] = pref[i] + seg[i];

    for (ll qi = 0; qi < Q; qi++) {
        ll lim;
        scanf("%lld", &lim);

        if (lim < mandatory) {
            printf("-1\n");
            continue;
        }

        // Need reducible losses <= need
        ll need = lim - mandatory;

        // Binary search minimum positive integer L in [1, N]
        ll lo = 1, hi = N, ans = N;
        while (lo <= hi) {
            ll mid = (lo + hi) >> 1;

            // sum max(seg[i] - mid, 0)
            // find first index with seg[i] > mid
            ll l = 0, r = K;
            while (l < r) {
                ll m = (l + r) >> 1;
                if (seg[m] <= mid) l = m + 1;
                else r = m;
            }
            ll idx = l;
            ll cnt = K - idx;
            ll sumTail = pref[K] - pref[idx];
            ll losses = sumTail - cnt * mid;

            if (losses <= need) {
                ans = mid;
                hi = mid - 1;
            } else {
                lo = mid + 1;
            }
        }

        printf("%lld\n", ans);
    }

    free(p);
    free(seg);
    free(pref);
    return 0;
}

