import java.util.*;
import java.io.*;

public class Main {
    static int[] propellers;
    static int N, M;

    static long countLosses(int L) {
        long losses = 0;
        for (int x = 1; x <= N; x++) {
            int lo = x - L;
            int hi = x;
            // Check if any propeller in [lo, hi]
            // Binary search for first propeller >= lo
            int idx = lowerBound(lo);
            if (idx >= M || propellers[idx] > hi) {
                losses++;
            }
        }
        return losses;
    }

    static int lowerBound(int val) {
        int lo = 0, hi = M;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (propellers[mid] < val) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        N = Integer.parseInt(st.nextToken());
        M = Integer.parseInt(st.nextToken());
        int Q = Integer.parseInt(st.nextToken());

        propellers = new int[M];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < M; i++) {
            propellers[i] = Integer.parseInt(st.nextToken());
        }
        Arrays.sort(propellers);

        StringBuilder sb = new StringBuilder();
        for (int q = 0; q < Q; q++) {
            st = new StringTokenizer(br.readLine());
            long l = Long.parseLong(st.nextToken());

            // Binary search on L from 1 to N
            int lo = 1, hi = N;
            while (lo < hi) {
                int mid = (lo + hi) / 2;
                if (countLosses(mid) <= l) {
                    hi = mid;
                } else {
                    lo = mid + 1;
                }
            }
            sb.append(lo).append("\n");
        }
        System.out.print(sb);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // Fast scanner
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int N = fs.nextInt();
        int M = fs.nextInt();
        int Q = fs.nextInt();

        int[] cnt = new int[N + 1];
        for (int i = 0; i < M; i++) {
            int x = fs.nextInt();
            if (0 <= x && x <= N) cnt[x]++;
        }

        // good[L] = number of positions t in [1..N] such that interval [t-L, t]
        // contains at least one propeller.
        // losses[L] = N - good[L]
        //
        // For each t, let prev[t] = nearest propeller position <= t.
        // Then [t-L, t] contains a propeller iff prev[t] >= t-L  <=>  L >= t-prev[t].
        //
        // So each t contributes to all L >= need[t], where need[t] = t-prev[t].
        // Count frequency of need[t], then prefix-sum.

        int[] freqNeed = new int[N + 1];
        int last = -1_000_000_000;
        for (int t = 1; t <= N; t++) {
            if (cnt[t] > 0) last = t;
            if (cnt[0] > 0 && last < 0) last = 0; // propeller at 0 can help early positions
            int need;
            if (last < 0) {
                // no propeller in [0..t]
                need = N + 1; // impossible for any L<=N
            } else {
                need = t - last;
                if (need > N) need = N + 1;
            }
            if (need <= N) freqNeed[need]++;
        }

        int[] good = new int[N + 1];
        int running = 0;
        for (int L = 0; L <= N; L++) {
            running += freqNeed[L];
            good[L] = running;
        }

        int[] losses = new int[N + 1];
        for (int L = 0; L <= N; L++) {
            losses[L] = N - good[L];
        }

        // losses[L] is non-increasing in L.
        // For each query l, find minimum L with losses[L] <= l.
        StringBuilder sb = new StringBuilder();
        for (int qi = 0; qi < Q; qi++) {
            int limit = fs.nextInt();

            int lo = 0, hi = N;
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (losses[mid] <= limit) hi = mid;
                else lo = mid + 1;
            }
            sb.append(lo).append('\n');
        }

        System.out.print(sb.toString());
    }
}
